1: $ErrorActionPreference = 'Stop'
2: $taskSource = $PSScriptRoot
3: $taskRun = Join-Path $taskSource 'windows-reservation02'
4: $taskPython = 'C:\Python314\python.exe'
5: $taskNative = $null
6: $taskRunStarted = [DateTimeOffset]::UtcNow.ToString('o')
7: $taskClock = [Diagnostics.Stopwatch]::StartNew()
8: 
9: function Write-TaskJson([string]$taskPath, $taskValue) {
10:     $taskBytes = [Text.UTF8Encoding]::new($false).GetBytes(($taskValue | ConvertTo-Json -Depth 24) + "`n")
11:     $taskStream = [IO.FileStream]::new($taskPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::Read)
12:     try { $taskStream.Write($taskBytes); $taskStream.Flush($true) } finally { $taskStream.Dispose() }
13: }
14: function Get-TaskBinding([string]$taskPath) {
15:     $taskItem = Get-Item -LiteralPath $taskPath -ErrorAction Stop
16:     if ($taskItem.PSIsContainer -or ($taskItem.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw 'Plain pinned input required' }
17:     return [ordered]@{ bytes = $taskItem.Length; sha256 = (Get-FileHash -Algorithm SHA256 -LiteralPath $taskPath).Hash.ToLowerInvariant() }
18: }
19: 
20: if (Test-Path -LiteralPath $taskRun) { throw 'Fresh windows-reservation02 output required' }
21: $taskPinsPath = Join-Path $taskSource 'PINS.json'
22: $taskAdmissionPath = Join-Path $taskSource 'ROOT-ADMISSION.json'
23: $taskPinsBinding = Get-TaskBinding $taskPinsPath
24: $taskAdmissionBinding = Get-TaskBinding $taskAdmissionPath
25: $taskLauncherBinding = Get-TaskBinding $PSCommandPath
26: $taskPins = Get-Content -LiteralPath $taskPinsPath -Raw | ConvertFrom-Json
27: $taskAdmission = Get-Content -LiteralPath $taskAdmissionPath -Raw | ConvertFrom-Json
28: if ($taskAdmission.approved -cne $true -or $taskAdmission.label -cne 'windows-reservation02' -or
29:     $taskAdmission.pins_sha256 -cne $taskPinsBinding.sha256 -or
30:     $taskAdmission.scope -cne 'generated_bytes_and_fake_ports_only') { throw 'Exact root admission required' }
31: $taskRows = @($taskPins.files)
32: if ($taskRows.Count -ne 28 -or @($taskRows.path | Sort-Object -Unique).Count -ne 28) { throw 'Exact 28-entry input map required' }
33: $taskBefore = @()
34: foreach ($taskRow in $taskRows) {
35:     if ($taskRow.path -cnotmatch '^[A-Za-z0-9_.-]+$') { throw 'Flat input name required' }
36:     $taskPath = Join-Path $taskSource $taskRow.path
37:     $taskActual = Get-TaskBinding $taskPath
38:     if ($taskActual.sha256 -cne $taskRow.sha256 -or $taskActual.bytes -ne $taskRow.bytes) { throw 'Pinned input mismatch' }
39:     $taskBefore += [ordered]@{ name = $taskRow.path; bytes = $taskActual.bytes; sha256 = $taskActual.sha256 }
40: }
41: New-Item -ItemType Directory -Path $taskRun -ErrorAction Stop | Out-Null
42: foreach ($taskRow in $taskRows) { Copy-Item -LiteralPath (Join-Path $taskSource $taskRow.path) -Destination (Join-Path $taskRun $taskRow.path) -ErrorAction Stop }
43: Copy-Item -LiteralPath $taskPinsPath -Destination (Join-Path $taskRun 'PINS.json') -ErrorAction Stop
44: Copy-Item -LiteralPath $taskAdmissionPath -Destination (Join-Path $taskRun 'ROOT-ADMISSION.json') -ErrorAction Stop
45: $taskControls = @(
46:     [ordered]@{name='PINS.json'; binding=$taskPinsBinding},
47:     [ordered]@{name='ROOT-ADMISSION.json'; binding=$taskAdmissionBinding},
48:     [ordered]@{name='run_preflight01.ps1'; binding=$taskLauncherBinding}
49: )
50: foreach ($taskRow in $taskBefore) {
51:     $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskRow.name)
52:     if ($taskCopy.sha256 -cne $taskRow.sha256 -or $taskCopy.bytes -ne $taskRow.bytes) { throw 'Copied input mismatch' }
53: }
54: foreach ($taskControl in $taskControls) {
55:     $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskControl.name)
56:     if ($taskCopy.sha256 -cne $taskControl.binding.sha256 -or $taskCopy.bytes -ne $taskControl.binding.bytes) { throw 'Copied control mismatch' }
57: }
58: $taskRemovedNames = @()
59: foreach ($taskEnv in @(Get-ChildItem Env:)) {
60:     if ($taskEnv.Name -match '(?i)(ANTHROPIC|OPENAI|GEMINI|GOOGLE_API|GROK|XAI|AZURE_OPENAI|HF_TOKEN|HUGGING_FACE|API_KEY|ACCESS_TOKEN|PROXY|PYTHONPATH|PYTHONHOME|PYTHONSTARTUP|PYTHONUSERBASE|VIRTUAL_ENV)') {
61:         $taskRemovedNames += $taskEnv.Name
62:         Remove-Item -LiteralPath ('Env:' + $taskEnv.Name)
63:     }
64: }
65: $env:IG_FORBIDDEN_LIVE = 'C:\Users\hello\AppData\Local\Uoink\index.db'
66: Write-TaskJson (Join-Path $taskRun 'plan.json') ([ordered]@{
67:     schema='uoink.windows-reservation-fake-launch.v1'; label='windows-reservation02'; python=$taskPython;
68:     arguments=@('-I','-S','-B',(Join-Path $taskRun 'qualify_windows_reservations.py'));
69:     started_utc=$taskRunStarted; before=$taskBefore; controls=$taskControls;
70:     removed_environment_names=$taskRemovedNames; startup_binding_set=$true;
71:     scope='generated_bytes_and_fake_ports_only'
72: })
73: 
74: try {
75:     $PSNativeCommandUseErrorActionPreference = $false
76:     & $taskPython -I -S -B (Join-Path $taskRun 'qualify_windows_reservations.py') 1> (Join-Path $taskRun 'stdout.json') 2> (Join-Path $taskRun 'stderr.log')
77:     $taskNative = $global:LASTEXITCODE
78:     Write-TaskJson (Join-Path $taskRun 'native-exit.json') ([ordered]@{
79:         native_exit=$taskNative; finished_utc=[DateTimeOffset]::UtcNow.ToString('o');
80:         elapsed_seconds=$taskClock.Elapsed.TotalSeconds
81:     })
82:     $taskAfter = @()
83:     foreach ($taskRow in $taskBefore) {
84:         $taskOriginal = Get-TaskBinding (Join-Path $taskSource $taskRow.name)
85:         $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskRow.name)
86:         $taskAfter += [ordered]@{name=$taskRow.name; original=$taskOriginal; copy=$taskCopy;
87:             unchanged=($taskOriginal.sha256 -ceq $taskRow.sha256 -and $taskCopy.sha256 -ceq $taskRow.sha256 -and
88:                 $taskOriginal.bytes -eq $taskRow.bytes -and $taskCopy.bytes -eq $taskRow.bytes)}
89:     }
90:     $taskAfterControls = @()
91:     foreach ($taskControl in $taskControls) {
92:         $taskOriginal = Get-TaskBinding (Join-Path $taskSource $taskControl.name)
93:         $taskCopy = Get-TaskBinding (Join-Path $taskRun $taskControl.name)
94:         $taskAfterControls += [ordered]@{name=$taskControl.name; original=$taskOriginal; copy=$taskCopy;
95:             unchanged=($taskOriginal.sha256 -ceq $taskControl.binding.sha256 -and $taskCopy.sha256 -ceq $taskControl.binding.sha256 -and
96:                 $taskOriginal.bytes -eq $taskControl.binding.bytes -and $taskCopy.bytes -eq $taskControl.binding.bytes)}
97:     }
98:     $taskInputsOkay = @($taskAfter | Where-Object { $_.unchanged -ne $true }).Count -eq 0 -and
99:         @($taskAfterControls | Where-Object { $_.unchanged -ne $true }).Count -eq 0
100:     Write-TaskJson (Join-Path $taskRun 'input-check.json') ([ordered]@{inputs=$taskAfter; controls=$taskAfterControls; inputs_unchanged=$taskInputsOkay})
101:     $taskStdout = Get-Item -LiteralPath (Join-Path $taskRun 'stdout.json')
102:     $taskStderr = Get-Item -LiteralPath (Join-Path $taskRun 'stderr.log')
103:     if ($taskStdout.Length -gt 262144) { throw 'Raw receipt exceeds bound' }
104:     $taskResult = Get-Content -LiteralPath $taskStdout.FullName -Raw | ConvertFrom-Json
105:     $taskExpected = @(Get-Content -LiteralPath (Join-Path $taskRun 'EXPECTED-CASES.json') -Raw | ConvertFrom-Json)
106:     $taskCaseIds = @($taskResult.cases | ForEach-Object { $_.id })
107:     $taskMembership = ($taskCaseIds.Count -eq 65 -and $taskExpected.Count -eq 65 -and
108:         (($taskCaseIds | ConvertTo-Json -Compress) -ceq ($taskExpected | ConvertTo-Json -Compress)))
109:     $taskGuardsOkay = @($taskResult.guards.PSObject.Properties).Count -eq 10 -and
110:         @($taskResult.guards.PSObject.Properties | Where-Object { $_.Value -cne $true }).Count -eq 0
111:     $taskValid = ($taskNative -is [int] -and $taskNative -eq 0 -and $taskResult.qualification_exit -eq 0 -and
112:         $taskResult.passed -eq 65 -and $taskResult.failed -eq 0 -and $taskResult.skipped -eq 0 -and
113:         $taskMembership -and $taskGuardsOkay -and $taskResult.guard_valid -ceq $true -and
114:         $taskResult.membership_valid -ceq $true -and $taskInputsOkay -and $taskStderr.Length -eq 0 -and
115:         @($taskResult.guard_denials).Count -eq 0 -and @($taskResult.registry_denials).Count -eq 0)
116:     Write-TaskJson (Join-Path $taskRun 'exit.json') ([ordered]@{
117:         native_exit=$taskNative; qualification_exit=$taskResult.qualification_exit;
118:         valid=$taskValid; inputs_unchanged=$taskInputsOkay; membership_valid=$taskMembership;
119:         guards_valid=$taskGuardsOkay; passed=$taskResult.passed; failed=$taskResult.failed; skipped=$taskResult.skipped;
120:         stdout_bytes=$taskStdout.Length; stderr_bytes=$taskStderr.Length;
121:         finished_utc=[DateTimeOffset]::UtcNow.ToString('o'); elapsed_seconds=$taskClock.Elapsed.TotalSeconds
122:     })
123:     if (-not $taskValid) { exit 1 }
124:     Write-Output 'windows-reservation02: 65 passed, 0 failed, 0 skipped; generated scope only.'
125:     exit 0
126: } catch {
127:     Write-TaskJson (Join-Path $taskRun 'launch-failure.json') ([ordered]@{
128:         native_exit=$taskNative; failure_type=$_.Exception.GetType().FullName;
129:         message=$_.Exception.Message; finished_utc=[DateTimeOffset]::UtcNow.ToString('o')
130:     })
131:     throw
132: }
